public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the start and end coordinates are within the valid range
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Create a 2D array to represent the maze
    boolean[][] maze = new boolean[n][n];
    for (int[] path : paths) {
        maze[path[0]][path[1]] = true;
    }

    // Use a queue to perform BFS
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    boolean[][] visited = new boolean[n][n];
    visited[start[0]][start[1]] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Explore all four possible directions
        int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        for (int[] direction : directions) {
            int newX = current[0] + direction[0];
            int newY = current[1] + direction[1];
            if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY] && maze[newX][newY]) {
                visited[newX][newY] = true;
                queue.offer(new int[]{newX, newY});
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
