    int totalLetters = word1.length() + word2.length();

    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }

    if (totalLetters == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(commonLetters, totalLetters);
    return "appx(" + word1 + ", " + word2 + ") = " + commonLetters / gcd + "/" + totalLetters / gcd;
}

