    while (fib[fib.length - 1] < k) {
        fib = Arrays.copyOf(fib, fib.length + 1);
        fib[fib.length - 1] = fib[fib.length - 2] + fib[fib.length - 3];
    }

    int count = 0;
    for (int i = fib.length - 1; i >= 0 && k > 0; i--) {
        if (k >= fib[i]) {
            k -= fib[i];
            count++;
        }
    }

    return count;
}

