public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Check horizontal lines
    for (int i = 0; i < m; i++) {
        int currentLength = 0;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                currentLength++;
            } else {
                maxLength = Math.max(maxLength, currentLength);
                currentLength = 0;
            }
        }
        maxLength = Math.max(maxLength, currentLength);
    }

    // Check vertical lines
    for (int j = 0; j < n; j++) {
        int currentLength = 0;
        for (int i = 0; i < m; i++) {
            if (mat[i][j] == 1) {
                currentLength++;
            } else {
                maxLength = Math.max(maxLength, currentLength);
                currentLength = 0;
            }
        }
        maxLength = Math.max(maxLength, currentLength);
    }

    // Check diagonal lines
    for (int i = 0, j = 0; i < m && j < n; i++, j++) {
        int currentLength = 0;
        while (i < m && j < n && mat[i][j] == 1) {
            currentLength++;
            i++;
            j++;
        }
        maxLength = Math.max(maxLength, currentLength);
    }

    // Check anti-diagonal lines
    for (int i = 0, j = n - 1; i < m && j >= 0; i++, j--) {
        int currentLength = 0;
        while (i < m && j >= 0 && mat[i][j] == 1) {
            currentLength++;
            i++;
            j--;
        }
        maxLength = Math.max(maxLength, currentLength);
    }

    return maxLength;
}

