public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] count = new int[n];
    int[] visited = new int[n];
    int result = 0;

    // Count the frequency of each element in the array
    for (int i = 0; i < n; i++) {
        count[A[i]]++;
    }

    // Check if the array can be permuted into a square array
    if (!isSquareArray(count)) {
        return 0;
    }

    // Generate all permutations of the array
    generatePermutations(A, 0, count, visited, result);

    return result;
}

private static boolean isSquareArray(int[] count) {
    for (int i = 0; i < count.length; i++) {
        if (count[i] % 2 != 0) {
            return false;
        }
    }
    return true;
}

private static void generatePermutations(int[] A, int index, int[] count, int[] visited, int& result) {
    if (index == A.length) {
        result++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (visited[i] == 0 && count[A[i]] > 0) {
            visited[i] = 1;
            A[index] = A[i];
            if (isSquareArray(count)) {
                generatePermutations(A, index + 1, count, visited, result);
            }
            visited[i] = 0;
            count[A[i]]++;
        }
    }
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    int[] leftSmaller = new int[heights.length];
    int[] rightSmaller = new int[heights.length];

    // Find the nearest smaller element to the left of each element
    leftSmaller[0] = -1;
    for (int i = 1; i < heights.length; i++) {
        int j = i - 1;
        while (j >= 0 && heights[j] >= heights[i]) {
            j = leftSmaller[j];
        }
        leftSmaller[i] = j;
    }

    // Find the nearest smaller element to the right of each element
    rightSmaller[heights.length - 1] = heights.length;
    for (int i = heights.length - 2; i >= 0; i--) {
        int j = i + 1;
        while (j < heights.length && heights[j] >= heights[i]) {
            j = rightSmaller[j];
        }
        rightSmaller[i] = j;
    }

    // Calculate the area of each rectangle and find the maximum
    for (int i = 0; i < heights.length; i++) {
        int width = rightSmaller[i] - leftSmaller[i] - 1;
        int area = width * heights[i];
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

