}

public static int findSmallestInteger(int n) {
    if (n <= 9) {
        return -1; // No possible rearrangement greater than n
    }

    int[] digits = new int[10];
    int count = 0;

    // Count the frequency of each digit in n
    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
        count++;
    }

    // Find the smallest digit that can be placed in the first position
    int smallest = 0;
    while (digits[smallest] == 0) {
        smallest++;
    }

    // Remove the smallest digit from the count
    digits[smallest]--;
    count--;

    // Place the smallest digit in the first position
    int result = smallest;

    // Place the remaining digits in ascending order
    for (int i = 0; i < count; i++) {
        int nextSmallest = 0;
        while (digits[nextSmallest] == 0) {
            nextSmallest++;
        }
        digits[nextSmallest]--;
        result = result * 10 + nextSmallest;
    }

    return result;
}

